    removeArrayEntry(key,index){this.form[key].splice(index,1)},
    addDeepDiveSection(key){if(!Array.isArray(this.form[key]?.locked))this.$set(this.form[key],'locked',[]);this.form[key].locked.push('')},
    removeDeepDiveSection(key,index){this.form[key]?.locked?.splice(index,1)},
    updateDeepDiveSection(key,index,value){if(Array.isArray(this.form[key]?.locked))this.$set(this.form[key].locked,index,value)},
    removeSettingsImage(){this.settings.ogImage='';this.$message.success('图片已移除，请保存设置')},
    removeFormImage(key){this.$set(this.form,key,'');this.$message.success('图片已移除，请保存后生效')},
    removeNestedImage(parentKey,index,subKey){const entry=this.form[parentKey]?.[index];if(!entry)return;this.$set(entry,subKey,'');this.$message.success('图片已移除，请保存后生效')},
    async uploadImage(req,key){try{if(!/^image\/(png|jpeg|webp)$/.test(req.file.type))throw new Error('仅支持 PNG、JPG 或 WebP 图片');if(req.file.size>6*1024*1024)throw new Error('图片大小需在 6MB 以内');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(req.file)});const result=await this.request('/admin/upload-image',{method:'POST',body:JSON.stringify({name:req.file.name,type:req.file.type,data,...(key==='og'?{}:{prefix:key,updateSettings:false})})});if(key==='og')this.settings.ogImage=result.path;else this.$set(this.form,key,result.path);this.$message.success('图片上传成功');req.onSuccess(result)}catch(e){this.$message.error('图片上传失败：'+e.message);req.onError(e)}},
    async uploadNestedImage(req,parentKey,index,subKey){try{if(!/^image\/(png|jpeg|webp)$/.test(req.file.type))throw new Error('仅支持 PNG、JPG 或 WebP 图片');if(req.file.size>6*1024*1024)throw new Error('图片大小需在 6MB 以内');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(req.file)});const result=await this.request('/admin/upload-image',{method:'POST',body:JSON.stringify({name:req.file.name,type:req.file.type,data,prefix:parentKey,updateSettings:false})});this.$set(this.form[parentKey][index],subKey,result.path);this.$message.success('图片上传成功');req.onSuccess(result)}catch(e){this.$message.error('图片上传失败：'+e.message);req.onError(e)}},
    async uploadGuideMap(req){try{await this.uploadImage(req,'mapImage');if(this.form.mapImage){this.$set(this.form.guide,'mapImage',this.form.mapImage);this.$delete(this.form,'mapImage')}}catch(e){req.onError(e)}},
    async uploadAudio(req){try{const file=req.file;if(!/\.(mp3|m4a)$/i.test(file.name)||!/^audio\/(mpeg|mp3|mp4|x-m4a|m4a)$/.test(file.type||''))throw new Error('仅支持 MP3/M4A 音频');if(!file.size||file.size>30*1024*1024)throw new Error('音频须小于 30MB 且不可为空');this.busy=true;const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const result=await this.request('/admin/upload-audio',{method:'POST',body:JSON.stringify({name:file.name,type:file.type,data,previewSeconds:this.form.previewSeconds})});['audioFile','previewFile','durationSeconds','previewSeconds'].forEach(key=>this.$set(this.form,key,result[key]));this.$message.success('音频已安全上传，并生成不超过 60 秒的试听文件');req.onSuccess(result)}catch(e){this.$message.error('音频上传失败：'+e.message);req.onError(e)}finally{this.busy=false}},
    async saveEditor(){this.jsonError='';const valid=await new Promise(resolve=>this.$refs.editForm.validate(resolve));if(!valid)return;try{this.busy=true;const payload={...this.form};for(const field of this.editor.fields.filter(f=>f.type==='json')){try{payload[field.key]=JSON.parse(this.jsonFields[field.key]||'{}')}catch(e){this.jsonError=field.label+' JSON 格式无效：'+e.message;return}}if(['routes','attractions'].includes(this.active)&&payload.tags!=null)payload.tags=this.tagValues(payload.tags);if(typeof payload.attractionIds==='string')payload.attractionIds=payload.attractionIds.split(/[,，、\s]+/).filter(Boolean);if(this.active==='destinations')payload.attractionId=payload.attractionIds?.[0]||'';if(this.active==='customTrips'&&this.dateRange?.length===2)payload.period=this.dateRange.join(' ~ ');if(this.active==='homeBanners'){const list=this.data.homeBanners.slice();if(this.editor.isNew)list.push(payload);else{const i=list.findIndex(x=>x.id===this.editor.rowId);if(i>=0)list.splice(i,1,payload)}await this.request('/admin/home-banners',{method:'PUT',body:JSON.stringify({items:list})});this.closeEditor();await this.loadAll();this.$message.success('Banner 已保存');return}const endpoint=this.currentMenu.endpoint;const method=this.editor.isNew?'POST':'PATCH';const id=encodeURIComponent(this.editor.rowId);const result=await this.request('/admin/'+endpoint+(this.editor.isNew?'':'/'+id),{method,body:JSON.stringify(payload)});this.closeEditor();await this.loadAll();this.$message.success(result?.token?'保存成功，分享链接 /trip/'+result.token:'保存成功')}catch(e){this.$message.error(e.message)}finally{this.busy=false}},
    async changeStatus(row,status){try{const endpoint=this.currentMenu.endpoint;const id=encodeURIComponent(row.key||row.id);const path=this.active==='miniprogramTrips'?'/admin/leads/'+id:'/admin/'+endpoint+'/'+id;let patch={status};if(['countries','guides','destinationTypes','homeBanners','miniprogramBanners'].includes(this.active))patch={enabled:status==='published'};await this.request(path,{method:'PATCH',body:JSON.stringify(patch)});await this.loadAll();this.$message.success('状态已更新')}catch(e){this.$message.error(e.message);this.loadAll()}},
    confirm(message){return new Promise(resolve=>{this.confirmText=message;this.confirmHandler=resolve;this.confirmVisible=true})},
    resolveConfirm(value){this.confirmVisible=false;this.confirmHandler?.(value);this.confirmHandler=null},
    async deleteRow(row){if(!await this.confirm('确定删除这条内容吗？此操作不可撤销。'))return;try{await this.request('/admin/'+this.currentMenu.endpoint+'/'+encodeURIComponent(row.key||row.id),{method:'DELETE'});await this.loadAll();this.$message.success('已删除')}catch(e){this.$message.error(e.message)}},
    async copyGuide(row){if(!await this.confirm('将复制此导游的多语言文案、头像、资质、擅长方向与评价为新草稿，确认继续？'))return;const copy=JSON.parse(JSON.stringify(row));copy.id=(row.id||'guide')+'-copy-'+Date.now().toString(36);copy.name=(copy.name||'导游')+'（副本）';copy.enabled=false;copy.featured=false;this.openEditor(copy,true);this.$message.info('已复制为未发布草稿，请修改导游 ID 与姓名后保存')},
    async saveSettings(){try{this.busy=true;await this.request('/admin/settings',{method:'PATCH',body:JSON.stringify(this.settings)});await this.loadAll();this.$message.success('站点配置已保存')}catch(e){this.$message.error(e.message)}finally{this.busy=false}}
  }
}
</script>
<style>@import './admin-element.css';.rich-text-control{width:100%;border:1px solid #dcdfe6;border-radius:4px;background:#fff}.rich-text-toolbar{display:flex;gap:6px;padding:6px;border-bottom:1px solid #ebeef5}.rich-text-toolbar button{border:1px solid #dcdfe6;background:#fff;border-radius:3px;padding:3px 8px;cursor:pointer;color:#344054}.rich-text-editable{min-height:90px;padding:10px;outline:none;line-height:1.6}.rich-text-editable:empty:before{content:'输入说明；支持粗体、斜体、列表与安全链接';color:#a0a5ad}</style>
